import { ScrollView, View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "1", name: "Чихэвч", price: "159,000₮" },
  { id: "2", name: "Гар цаг", price: "249,000₮" },
  { id: "3", name: "Нарны шил", price: "89,000₮" },
  { id: "4", name: "Цүнх", price: "129,000₮" },
];

function App() {
  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
      {PRODUCTS.map((p) => (
        <View key={p.id} testID="product" style={styles.card}>
          <Text style={styles.name}>{p.name}</Text>
          <Text style={styles.price}>{p.price}</Text>
        </View>
      ))}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: "#f5f6f8" },
  content: { padding: 16, gap: 12 },
  card: { backgroundColor: "#ffffff", padding: 16, borderRadius: 14, flexDirection: "row", justifyContent: "space-between" },
  name: { fontSize: 16, fontWeight: "600" },
  price: { fontSize: 16, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
